  const ver=(movs,titulo)=>{if(!f79PuedeCompararTurnos())return;modal({titulo,ancho:true,cuerpo:movs.length?`<div class="table-scroll"><table class="mtable"><thead><tr><th>Producto / responsable</th><th>Fecha</th><th>Tipo / motivo</th><th class="r">Cantidad</th></tr></thead><tbody>${[...movs].sort((a,b)=>String(a.fecha).localeCompare(String(b.fecha))).map(m=>`<tr><td>${esc(prod(m.prodId)?.nombre||'Producto no disponible')}<br>${esc(responsableMovimiento(m))}</td><td>${fFH(m.fecha)}</td><td>${esc(m.tipo)}<br>${esc(m.motivo||'')}</td><td>${fmtCant(prod(m.prodId),Number(m.cant)||0)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Sin movimientos registrados en este turno.</div>',pie:'<button class="btn ghost" data-cerrar>Cerrar</button>'});};
  $$('[data-mov-turno-detalle]',cont).forEach(b=>b.onclick=()=>{const r=d.filas.find(r=>r.producto.id===b.dataset.prod);if(r)ver(r.turnos[Number(b.dataset.movTurnoDetalle)].movs,'Movimientos del turno');});
  const sinTurno=$('#movSinTurno',cont);if(sinTurno)sinTurno.onclick=()=>ver(d.sinTurno,'Movimientos sin turno asignado');
