let temporizadorBusquedaMovimientos=null;
function f80CancelarBusquedaMovimientos(){clearTimeout(temporizadorBusquedaMovimientos);temporizadorBusquedaMovimientos=null;}
function f80BuscarMovimientos(e){
  filtrosMovimientos.q=e.target.value;
  f80CancelarBusquedaMovimientos();
  if(movVista==='turnos'&&f79PuedeCompararTurnos()){
    const control=e.target;
    temporizadorBusquedaMovimientos=setTimeout(()=>{
      temporizadorBusquedaMovimientos=null;
      if(control.isConnected&&$('#qMovimientos')===control&&movVista==='turnos'&&f79PuedeCompararTurnos())pintarMovimientosActual();
    },180);
  }else pintarMovimientosActual();
}
/* REV80_MOVIMIENTOS_BUSQUEDA_END */
function pintarMovimientosActual(){f80CancelarBusquedaMovimientos();if(movVista==='turnos'&&f79PuedeCompararTurnos())pintarMovimientosTurnos();else pintarMovimientosDia();}

