  if(!f79PuedeCompararTurnos())movVista='periodo';
  const opciones=f79OpcionesTurnos();
  if(!opciones.some(t=>t.id===movTurnoA))movTurnoA=opciones[0]?.id||'';
  if(!opciones.some(t=>t.id===movTurnoB))movTurnoB=opciones[1]?.id||'';
