  m.innerHTML=`
  <div class="head">
    <div><h1>Movimientos de stock</h1><div class="sub">Auditá ingresos, ventas y ajustes, y corregí diferencias desde el mismo lugar.</div></div>
  </div>
  ${f79PuedeCompararTurnos()?`<div class="cash-tabs" aria-label="Consulta de stock"><button type="button" class="cash-tab ${movVista==='periodo'?'active':''}" data-mov-vista="periodo">Por período</button><button type="button" class="cash-tab ${movVista==='turnos'?'active':''}" data-mov-vista="turnos">Comparar turnos</button></div>`:''}
  <div class="card" style="margin-bottom:16px"><div class="card-b">
    <div class="row" style="align-items:flex-end">
      ${movVista==='turnos'?selectTurno('movTurnoA',movTurnoA)+selectTurno('movTurnoB',movTurnoB):`
      <div style="min-width:180px"><label class="f" for="movRango">Período</label><select class="inp" id="movRango"><option value="dia" ${movRango==='dia'?'selected':''}>Un día</option><option value="7" ${movRango==='7'?'selected':''}>Últimos 7 días</option><option value="30" ${movRango==='30'?'selected':''}>Últimos 30 días</option></select></div>
      <div style="min-width:180px"><label class="f" for="fechaMovimientos">Hasta</label><input type="date" class="inp" id="fechaMovimientos" value="${esc(fechaMovimientos)}" max="${hoy()}"></div>
      `}
      <div style="flex:2;min-width:220px"><label class="f" for="qMovimientos">Buscar producto</label><input class="inp" id="qMovimientos" value="${esc(filtrosMovimientos.q)}" placeholder="Nombre o código…" autocomplete="off"></div>
      <div style="flex:1;min-width:180px"><label class="f" for="rubroMovimientos">Rubro</label><select class="inp" id="rubroMovimientos"><option value="">Todos los rubros</option>${rubros().map(r=>`<option value="${esc(r)}" ${filtrosMovimientos.rubro===r?'selected':''}>${esc(r)}</option>`).join('')}</select></div>
    </div>
  </div></div>
  <div class="nota-dash" style="margin-bottom:16px">${movVista==='turnos'?'Compará ingresos, ventas y ajustes de cada turno. El stock global incluye todas las cajas del comercio.':'La cuenta se lee de izquierda a derecha: stock inicial + ingresos − ventas ± ajustes = stock final. Tocá “Detalle” para ver hora, motivo y responsable disponible.'}</div>
  <div class="card">
    <div class="card-h"><h2>${movVista==='turnos'?'Comparación de turnos':'Detalle del día'}</h2><span class="pill mute" id="cuentaMovimientos"></span></div>
    <div id="tablaMovimientos"></div>
  </div>`;
  const fecha=$('#fechaMovimientos');if(fecha)fecha.onchange=e=>{fechaMovimientos=e.target.value||hoy();pintarMovimientosActual();};
  const rango=$('#movRango');if(rango)rango.onchange=e=>{movRango=e.target.value;pintarMovimientosActual();};
